begin;
do $$declare tab text;constraint_name text;begin
 foreach tab in array array['intelligence_policies','intelligence_runs']loop
  for constraint_name in select conname from pg_constraint where conrelid=format('app.%I',tab)::regclass and contype='c'and pg_get_constraintdef(oid)like'%data_classification%'loop execute format('alter table app.%I drop constraint %I',tab,constraint_name);end loop;
  execute format('alter table app.%I add check(data_classification in(''SCHOOL_CUSTOM_NUMERIC'',''SCHOOL_CUSTOM_NATIVE''))',tab);
 end loop;
end$$;
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.approve_school_intelligence_policy(jsonb,text,text,text)'::regprocedure);
 anchor:='input->>''dataClassification''is distinct from''SCHOOL_CUSTOM_NUMERIC''';if position(anchor in definition)=0 then raise exception 'School native classification source changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,'(input->>''dataClassification''is null or input->>''dataClassification''not in(''SCHOOL_CUSTOM_NUMERIC'',''SCHOOL_CUSTOM_NATIVE''))');
 definition:=replace(definition,'''NEXT_LEARNING_ACTION'',''SCHOOL_CUSTOM_NUMERIC'',actions','''NEXT_LEARNING_ACTION'',input->>''dataClassification'',actions');
 definition:=replace(definition,'live_enabled=excluded.live_enabled,allowed_actions=excluded.allowed_actions','live_enabled=excluded.live_enabled,data_classification=excluded.data_classification,allowed_actions=excluded.allowed_actions');execute definition;
end$$;
create or replace function internal.intelligence_context(baseline_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();source internal.improvement_result_sources;reference app.school_custom_references;version app.school_custom_versions;begin
 if not"authorization".can_manage_baseline(school,baseline_id)then raise exception 'Analysis native source denied'using errcode='42501';end if;
 select*into source from internal.improvement_result_sources where school_id=school and id=baseline_id;select*into reference from app.school_custom_references where school_id=school and id=source.reference_id;select*into version from app.school_custom_versions where school_id=school and id=reference.version_id;
 if source.id is null or reference.status is distinct from'APPROVED'or version.source_type is distinct from'SCHOOL_AUTHORED'or version.rights_status is distinct from'PERMITTED'or version.version is distinct from source.reference_version then raise exception 'Approved native evidence required'using errcode='P0002';end if;
 return jsonb_build_object('resultId',source.id,'evidenceId',source.evidence_id,'referenceId',source.reference_id,'referenceVersion',source.reference_version)||case when source.model='numeric'then jsonb_build_object('score',source.score,'maxScore',source.max_score)else jsonb_build_object('nativeResult',source.native_result)end;
end$$;
-- The same numeric reservation/state/lease path now reads its source identity from
-- the native projection; rubric processing requires explicit native school policy.
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.begin_intelligence_run(text,text,uuid,jsonb,text)'::regprocedure);
 definition:=replace(definition,'app.result_revisions','internal.improvement_result_sources');
 anchor:='token:=gen_random_uuid();';if position(anchor in definition)=0 then raise exception 'Native reservation source changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,'if r.model=''rubric''and not exists(select 1 from app.intelligence_policies policy where policy.school_id=r.school_id and policy.version=(settings->>''policyVersion'')::integer and policy.data_classification=''SCHOOL_CUSTOM_NATIVE'')then raise exception ''Explicit native rubric school policy required''using errcode=''22023'';end if;'||anchor);
 definition:=replace(definition,'''NEXT_LEARNING_ACTION'',''SCHOOL_CUSTOM_NUMERIC'',mode','''NEXT_LEARNING_ACTION'',(select data_classification from app.intelligence_policies where school_id=r.school_id),mode');execute definition;
 definition:=pg_get_functiondef('internal.begin_teacher_insight_run(text,text,uuid,jsonb,text)'::regprocedure);
 anchor:='when''2''then settings->>''promptDigest''is distinct from''1f892110e486d0f8117e53ef9d9cf0a884b7c155821dd8eb1284cef22b9f0de4''';if position(anchor in definition)=0 then raise exception 'Native prompt digest source changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,anchor||'when''3''then settings->>''promptDigest''is distinct from''02cb6c151d57fa9e7c17c861ccea6561c1a6c400fcd3814736eb01a22d442e2c''');
 anchor:='context:=internal.intelligence_context(baseline_id);';definition:=replace(definition,anchor,anchor||'if context?''nativeResult''and settings->>''promptVersion''is distinct from''3''then raise exception ''Native rubric prompt required''using errcode=''22023'';end if;');
 definition:=replace(definition,'from app.people p join app.result_revisions r','from app.people p join internal.improvement_result_sources r');execute definition;
end$$;
-- Existing numeric context selection remains unchanged; native rubric selection
-- is a model-specific source branch within the same owner and output envelope.
create function internal.teacher_native_insight_context(baseline_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();baseline internal.improvement_result_sources;course app.courses;reference app.school_custom_references;recent jsonb;observations jsonb;options jsonb;answer jsonb;begin
 perform internal.intelligence_context(baseline_id);select*into baseline from internal.improvement_result_sources where school_id=school and id=baseline_id;select c.*into course from app.assessments assessment join app.courses c on c.school_id=assessment.school_id and c.id=assessment.course_id where assessment.school_id=school and assessment.id=baseline.assessment_id;select*into reference from app.school_custom_references where school_id=school and id=baseline.reference_id;
 if baseline.model is distinct from'rubric'or course.id is null or not"authorization".can_read_course(school,course.id)or not"authorization".programme_course_allowed(school,course.id,baseline.learner_id)then raise exception 'Native insight source denied'using errcode='42501';end if;
 select coalesce(jsonb_agg(source order by priority,created_at desc,id),'[]'::jsonb)into recent from(select result.id,result.created_at,case when result.id=baseline_id then 0 else 1 end priority,jsonb_build_object('resultId',result.id,'evidenceId',result.evidence_id,'referenceId',result.reference_id,'referenceVersion',result.reference_version,'nativeResult',result.native_result)source from internal.improvement_result_sources result join app.assessments assessment on assessment.school_id=result.school_id and assessment.id=result.assessment_id where result.school_id=school and result.learner_id=baseline.learner_id and result.model='rubric'and assessment.course_id=course.id and result.reference_id=baseline.reference_id and result.reference_version=baseline.reference_version and internal.native_academic_source_allowed(school,result.id,true)order by(result.id=baseline_id)desc,result.created_at desc,result.id limit 10)bounded;
 select coalesce(jsonb_agg(source order by occurred_at desc,id),'[]'::jsonb)into observations from(select observed.id,observed.occurred_at,jsonb_build_object('id',observed.id,'kind',observed.kind,'sourceObjectId',observed.source_object_id,'sourceEventId',observed.source_event_id,'occurredAt',observed.occurred_at)source from internal.authorized_observation_sources(school,baseline.learner_id,clock_timestamp()-interval '14 days',null)authorized join app.habit_observations observed on observed.school_id=school and observed.id=authorized.id and observed.source_event_id=authorized.source_event_id where internal.observation_source_allowed(school,observed.id)and((observed.source_type='ACTIVITY_COMPLETION'and exists(select 1 from app.activity_completions completion join app.activities activity on activity.school_id=completion.school_id and activity.id=completion.activity_id join app.lessons lesson on lesson.school_id=activity.school_id and lesson.id=activity.lesson_id join app.units unit on unit.school_id=lesson.school_id and unit.id=lesson.unit_id where completion.school_id=school and completion.id=observed.source_object_id and unit.course_id=course.id))or(observed.source_type='SUBMISSION_REVISION'and exists(select 1 from app.submissions submission join app.assessments assessment on assessment.school_id=submission.school_id and assessment.id=submission.assessment_id where submission.school_id=school and submission.id=observed.source_object_id and assessment.course_id=course.id)))order by observed.occurred_at desc,observed.id limit 20)bounded;
 select coalesce(jsonb_agg(source order by sequence,id),'[]'::jsonb)into options from(select activity.id,activity.sequence,jsonb_build_object('activityId',activity.id,'title',activity.title,'instructions',activity.instructions,'kind',activity.kind)source from app.activities activity join app.lessons lesson on lesson.school_id=activity.school_id and lesson.id=activity.lesson_id join app.units unit on unit.school_id=lesson.school_id and unit.id=lesson.unit_id where activity.school_id=school and unit.course_id=course.id and course.status='PUBLISHED'and activity.kind in('practice','reflection','reading')and length(activity.instructions)<=4000 order by activity.sequence,activity.id limit 10)bounded;
 answer:=jsonb_build_object('schemaVersion','1','learnerId',baseline.learner_id,'courseId',course.id,'classId',course.class_id,'reference',jsonb_build_object('id',reference.id,'version',baseline.reference_version,'title',reference.title),'recentResults',recent,'observations',observations,'priorInterventions','[]'::jsonb,'learningOptions',options,'coverage','BOUNDED_AUTHORIZED_CONTEXT');if octet_length(answer::text)>65536 then raise exception 'Native context requires smaller source'using errcode='22023';end if;return answer;
end$$;
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.teacher_insight_context(uuid)'::regprocedure);anchor:='perform internal.intelligence_context(baseline_id);';if position(anchor in definition)=0 then raise exception 'Teacher context branch source changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,'if exists(select 1 from internal.improvement_result_sources native where native.school_id="authorization".school_id()and native.id=baseline_id and native.model=''rubric'')then return internal.teacher_native_insight_context(baseline_id);end if;'||anchor);execute definition;
end$$;
create function internal.require_native_insight_scope(target_run uuid)returns void language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();run app.intelligence_runs;stored jsonb;source jsonb;native_context jsonb;course uuid;begin
 select*into run from app.intelligence_runs where school_id=school and id=target_run;if run.id is null then raise exception 'Native stored run denied'using errcode='42501';end if;
 perform internal.require_intelligence_policy(run.generation_mode,run.policy_version);native_context:=internal.intelligence_context(run.baseline_result_id);
 if not(native_context?'nativeResult')or native_context is distinct from run.context_references then raise exception 'Native baseline changed'using errcode='42501';end if;
 if not exists(select 1 from app.intelligence_policies policy where policy.school_id=school and policy.version=run.policy_version and policy.data_classification='SCHOOL_CUSTOM_NATIVE')then raise exception 'Native saved policy scope denied'using errcode='42501';end if;
 select context into stored from app.intelligence_context_details where school_id=school and run_id=target_run;if stored is null then raise exception 'Native saved context missing'using errcode='42501';end if;course:=(stored->>'courseId')::uuid;
 for source in select*from jsonb_array_elements(stored->'recentResults')loop
  if not internal.native_academic_source_allowed(school,(source->>'resultId')::uuid,true)or not exists(select 1 from internal.improvement_result_sources result join app.assessments assessment on assessment.school_id=result.school_id and assessment.id=result.assessment_id where result.school_id=school and result.id=(source->>'resultId')::uuid and result.learner_id=run.learner_id and assessment.course_id=course and result.reference_id=(run.context_references->>'referenceId')::uuid and result.native_result=source->'nativeResult' and result.evidence_id=(source->>'evidenceId')::uuid and result.reference_version=source->>'referenceVersion' and result.reference_id=(source->>'referenceId')::uuid)then raise exception 'Native cited result denied'using errcode='42501';end if;
 end loop;
 for source in select*from jsonb_array_elements(stored->'observations')loop
  if not internal.observation_source_allowed(school,(source->>'id')::uuid)or not exists(select 1 from app.habit_observations observed where observed.school_id=school and observed.id=(source->>'id')::uuid and observed.learner_id=run.learner_id and observed.kind=source->>'kind'and observed.source_object_id=(source->>'sourceObjectId')::uuid and observed.source_event_id=(source->>'sourceEventId')::uuid and observed.occurred_at=(source->>'occurredAt')::timestamptz)then raise exception 'Native observation denied'using errcode='42501';end if;
 end loop;
 if jsonb_array_length(stored->'priorInterventions')<>0 then raise exception 'Native prior outcomes require comparable policy'using errcode='22023';end if;
 for source in select*from jsonb_array_elements(stored->'learningOptions')loop
  if not exists(select 1 from app.activities activity join app.lessons lesson on lesson.school_id=activity.school_id and lesson.id=activity.lesson_id join app.units unit on unit.school_id=lesson.school_id and unit.id=lesson.unit_id join app.courses source_course on source_course.school_id=unit.school_id and source_course.id=unit.course_id where activity.school_id=school and activity.id=(source->>'activityId')::uuid and unit.course_id=course and source_course.status='PUBLISHED'and activity.kind=source->>'kind'and activity.title=source->>'title'and activity.instructions=source->>'instructions'and"authorization".can_read_course(school,course)and"authorization".programme_course_allowed(school,course,run.learner_id))then raise exception 'Native option source changed'using errcode='42501';end if;
 end loop;
end$$;
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.require_stored_insight_scope(uuid)'::regprocedure);anchor:='select*into run from app.intelligence_runs';if position(anchor in definition)=0 then raise exception 'Saved source scope branch changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,'if exists(select 1 from app.intelligence_runs native where native.school_id="authorization".school_id()and native.id=target_run and native.context_references?''nativeResult'')then perform internal.require_native_insight_scope(target_run);return;end if;'||anchor);execute definition;
 definition:=pg_get_functiondef('internal.read_intelligence_run_status(integer,uuid,uuid)'::regprocedure);definition:=replace(definition,'app.result_revisions','internal.improvement_result_sources');execute definition;
 definition:=pg_get_functiondef('internal.insight_result_allowed(uuid,uuid,uuid,uuid,uuid,text,boolean)'::regprocedure);definition:=replace(definition,'app.result_revisions','internal.improvement_result_sources');definition:=replace(definition,'app.academic_evidence','internal.improvement_evidence_sources');definition:=replace(definition,'app.current_results','internal.improvement_current_results');execute definition;
end$$;
create function internal.validate_native_intelligence_analysis(target_run uuid,analysis jsonb)returns void language plpgsql security definer set search_path=''as $$declare run app.intelligence_runs;stored jsonb;source jsonb;basis text;begin
 select*into run from app.intelligence_runs where school_id="authorization".school_id()and id=target_run;select context into stored from app.intelligence_context_details where school_id=run.school_id and run_id=run.id;
 if analysis is null or jsonb_typeof(analysis)<>'object'or not(analysis?&array['basis','resultIds','observationIds','priorInterventionIds','interpretation','uncertainty'])or analysis-array['basis','resultIds','observationIds','priorInterventionIds','interpretation','uncertainty']<>'{}'::jsonb or analysis->>'interpretation'is distinct from'TEACHER_REVIEW_RECORDED_EVIDENCE'or analysis->>'uncertainty'is distinct from'EVIDENCE_NOT_CAUSAL'or jsonb_typeof(analysis->'resultIds')is distinct from'array'or jsonb_typeof(analysis->'observationIds')is distinct from'array'or jsonb_typeof(analysis->'priorInterventionIds')is distinct from'array' then raise exception 'Bounded native reasoning required'using errcode='22023';end if;
 if jsonb_array_length(analysis->'resultIds')not between 1 and 10 or jsonb_array_length(analysis->'observationIds')>20 or jsonb_array_length(analysis->'priorInterventionIds')<>0 or not(analysis->'resultIds'?run.baseline_result_id::text)then raise exception 'Native reasoning identities required'using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements_text(analysis->'resultIds')id where not exists(select 1 from jsonb_array_elements(stored->'recentResults')source where source->>'resultId'=id))or exists(select 1 from jsonb_array_elements_text(analysis->'observationIds')id where not exists(select 1 from jsonb_array_elements(stored->'observations')source where source->>'id'=id))then raise exception 'Unavailable native reasoning citation'using errcode='22023';end if;
 if(select count(distinct id)from jsonb_array_elements_text(analysis->'resultIds')id)<>jsonb_array_length(analysis->'resultIds')or(select count(distinct id)from jsonb_array_elements_text(analysis->'observationIds')id)<>jsonb_array_length(analysis->'observationIds')then raise exception 'Native reasoning duplicate citation'using errcode='22023';end if;
 basis:=analysis->>'basis';if basis='SINGLE_RESULT'then if jsonb_array_length(analysis->'resultIds')<>1 or jsonb_array_length(analysis->'observationIds')<>0 then raise exception 'Single native reasoning scope'using errcode='22023';end if;
 elsif basis in('RECORDED_PRACTICE','RECORDED_REFLECTION')then if jsonb_array_length(analysis->'observationIds')=0 or exists(select 1 from jsonb_array_elements_text(analysis->'observationIds')id where not exists(select 1 from jsonb_array_elements(stored->'observations')source where source->>'id'=id and source->>'kind'=case basis when'RECORDED_PRACTICE'then'practice'else'reflection'end))then raise exception 'Native observed reasoning scope'using errcode='22023';end if;
 else raise exception 'Rubric comparison requires reviewed native policy'using errcode='22023';end if;
end$$;
create function internal.complete_native_intelligence_run(target_run uuid,current_lease uuid,output jsonb,usage jsonb,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$declare run app.intelligence_runs;context jsonb;selected jsonb;action text;proposal uuid;response jsonb;tokens integer;inputs integer;cost_amount numeric;latency integer;basis text;begin
 select*into run from app.intelligence_runs where school_id="authorization".school_id()and id=target_run and actor_id="authorization".actor_id()for update;
 if not found then raise exception 'Native run denied'using errcode='42501';end if;perform internal.require_native_insight_scope(target_run);context:=run.context_references;
 if run.state<>'REASONING'or run.lease_token is distinct from current_lease or run.lease_until<=clock_timestamp()or run.prompt_version<>'3'then raise exception 'Native run source or lease changed'using errcode='22023';end if;
 if output is null or jsonb_typeof(output)<>'object'or output-array['evidenceIds','facts','action','reason','limitation','selectedActivityId','analysis']<>'{}'::jsonb or output->'evidenceIds'is distinct from jsonb_build_array(context->'evidenceId')or jsonb_typeof(output->'facts')is distinct from'array'or jsonb_array_length(output->'facts')<>1 or(output->'facts'->0)-'kind'is distinct from context or output->'facts'->0->>'kind'is distinct from'RUBRIC_RESULT'or output->>'reason'is distinct from'REVIEW_RECORDED_RESULT'or output->>'limitation'is distinct from'SINGLE_RESULT_NOT_CAUSAL'then raise exception 'Exact native output required'using errcode='22023';end if;
 action:=output->>'action';if action is null or not(action=any(run.allowed_actions))then raise exception 'Frozen native action denied'using errcode='22023';end if;
 perform internal.validate_native_intelligence_analysis(target_run,output->'analysis');
 if output?'selectedActivityId'then select option into selected from app.intelligence_context_details detail cross join lateral jsonb_array_elements(detail.context->'learningOptions')option where detail.school_id=run.school_id and detail.run_id=run.id and option->>'activityId'=output->>'selectedActivityId'and option->>'kind'='practice';if selected is null or action<>'GUIDED_PRACTICE'then raise exception 'Native selected practice denied'using errcode='22023';end if;end if;
 if usage is null or jsonb_typeof(usage)<>'object'or usage-array['outputTokens','inputTokens','cost','costBasis','latencyMs']<>'{}'::jsonb then raise exception 'Native usage required'using errcode='22023';end if;
 tokens:=(usage->>'outputTokens')::integer;inputs:=(usage->>'inputTokens')::integer;cost_amount:=(usage->>'cost')::numeric;latency:=(usage->>'latencyMs')::integer;basis:=usage->>'costBasis';
 if tokens is null or tokens not between 0 and run.max_tokens or inputs is null or inputs<0 or cost_amount is null or cost_amount<0 or cost_amount>run.max_cost or latency is null or latency<0 or latency>run.timeout_ms+1000 or basis is null or basis not in('DETERMINISTIC_FIXTURE','CONFIGURED_TOKEN_RATES','BUDGET_RESERVATION','LEGACY_UNSPECIFIED')or basis is distinct from run.cost_basis or(basis='DETERMINISTIC_FIXTURE'and(inputs<>0 or cost_amount<>0 or run.generation_mode<>'FIXTURE'))or(basis in('CONFIGURED_TOKEN_RATES','BUDGET_RESERVATION')and run.generation_mode<>'LIVE')or(basis='BUDGET_RESERVATION'and cost_amount is distinct from run.reserved_budget)then raise exception 'Native usage limits changed'using errcode='22023';end if;
 insert into app.recommendations(school_id,learner_id,reference_id,baseline_result_id,origin,generation_mode,intelligence_run_id,observation,interpretation,recommendation,rationale,uncertainty,activity_title,instructions,evidence_ids,created_by,selected_activity_id,analysis,prompt_digest)
 values(run.school_id,run.learner_id,(context->>'referenceId')::uuid,run.baseline_result_id,'AI_GENERATED',run.generation_mode,run.id,'The released rubric retains the cited criterion descriptors.','A teacher may review the native criterion evidence.',case action when'GUIDED_PRACTICE'then'Try the teacher-reviewed practice for this objective.'else'Review teacher feedback for the native criterion evidence.'end,'Exact rubric criteria are preserved; comparable attainment is unknown.','Recorded criterion evidence does not prove cause, traits or overall attainment.',coalesce(selected->>'title',case action when'GUIDED_PRACTICE'then'Guided practice'else'Review feedback'end),coalesce(selected->>'instructions','Review the native criterion evidence and explain one next step with your teacher.'),array[(context->>'evidenceId')::uuid],"authorization".actor_id(),(selected->>'activityId')::uuid,output->'analysis',run.prompt_digest)returning id into proposal;
 update app.intelligence_runs set state='PROPOSAL_READY',grounded_output=output,output_tokens=tokens,input_tokens=inputs,cost=cost_amount,latency_ms=latency,evaluation_status='PASSED',lease_token=null,lease_until=null,completed_at=clock_timestamp(),selected_activity_id=(selected->>'activityId')::uuid,analysis=output->'analysis'where school_id=run.school_id and id=run.id;
 select jsonb_build_object('id',source.id,'learnerId',source.learner_id,'referenceId',source.reference_id,'baselineResultId',source.baseline_result_id,'origin',source.origin,'generationMode',source.generation_mode,'intelligenceRunId',source.intelligence_run_id,'observation',source.observation,'evidenceIds',source.evidence_ids,'interpretation',source.interpretation,'recommendation',source.recommendation,'rationale',source.rationale,'uncertainty',source.uncertainty,'activityTitle',source.activity_title,'instructions',source.instructions,'status',source.status,'createdAt',source.created_at,'selectedActivityId',source.selected_activity_id,'analysis',source.analysis,'promptDigest',source.prompt_digest)into response from app.recommendations source where source.school_id=run.school_id and source.id=proposal;
 perform internal.append_audit('intelligence.proposal_ready','intelligence_run',run.id,request_id,'succeeded',jsonb_build_object('recommendationId',proposal,'generationMode',run.generation_mode,'evaluationStatus','PASSED'));perform internal.append_audit('recommendation.created','recommendation',proposal,request_id,'succeeded',jsonb_build_object('intelligenceRunId',run.id));perform internal.enqueue_event('recommendation.created','recommendation',proposal,1,jsonb_build_object('intelligenceRunId',run.id,'generationMode',run.generation_mode),'recommendation.created:'||proposal::text);perform internal.finish_command(run.command_key,'intelligence.analyze',run.fingerprint,response);return response;
end$$;
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.complete_intelligence_run(uuid,uuid,jsonb,jsonb,text)'::regprocedure);anchor:='select*into run from app.intelligence_runs';if position(anchor in definition)=0 then raise exception 'Native completion branch changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,'if exists(select 1 from app.intelligence_runs native where native.school_id="authorization".school_id()and native.id=target_run and native.context_references?''nativeResult'')then return internal.complete_native_intelligence_run(target_run,current_lease,output,usage,source_request_id);end if;'||anchor);execute definition;
end$$;
revoke execute on function internal.validate_native_intelligence_analysis(uuid,jsonb),internal.complete_native_intelligence_run(uuid,uuid,jsonb,jsonb,text)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
revoke execute on function internal.teacher_native_insight_context(uuid),internal.require_native_insight_scope(uuid)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
commit;
